package org.eclipse.rdf4j.query.algebra.evaluation.optimizer.cascades.packed;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.util.HashSet;
import java.util.LinkedHashSet;
import java.util.Random;
import java.util.Set;

import org.junit.jupiter.api.Test;

class PackedDphypEnumeratorTest {

	@Test
	void chainEmitsOnlyConnectedSubgraphComplementPairs() {
		PackedJoinHypergraph graph = chain(3);
		RecordingReceiver receiver = enumerate(graph);

		assertEquals(Set.of(new Pair(0b010L, 0b100L), new Pair(0b001L, 0b010L),
				new Pair(0b001L, 0b110L), new Pair(0b011L, 0b100L)), receiver.pairs);
		assertFalse(receiver.seen.contains(0b101L), "the disconnected {0,2} subset must never enter the memo");
	}

	@Test
	void complexEdgeWaitsForBothHypernodes() {
		PackedJoinHypergraph graph = new PackedJoinHypergraph(4);
		graph.addEdge(0b0001L, 0b0010L);
		graph.addEdge(0b0100L, 0b1000L);
		graph.addEdge(0b0011L, 0b1100L);

		RecordingReceiver receiver = enumerate(graph);

		assertEquals(Set.of(new Pair(0b0001L, 0b0010L), new Pair(0b0100L, 0b1000L),
				new Pair(0b0011L, 0b1100L)), receiver.pairs);
	}

	@Test
	void randomHypergraphsMatchIndependentDpsubOracle() {
		Random random = new Random(20260802L);
		for (int iteration = 0; iteration < 200; iteration++) {
			PackedJoinHypergraph graph = randomGraph(random);
			RecordingReceiver receiver = enumerate(graph);

			assertEquals(oraclePairs(graph), receiver.pairs, "DPhyp/DPsub mismatch at iteration " + iteration);
		}
	}

	private static RecordingReceiver enumerate(PackedJoinHypergraph graph) {
		RecordingReceiver receiver = new RecordingReceiver(graph);
		assertFalse(PackedDphypEnumerator.enumerate(graph, receiver));
		return receiver;
	}

	private static PackedJoinHypergraph chain(int nodes) {
		PackedJoinHypergraph graph = new PackedJoinHypergraph(nodes);
		for (int node = 1; node < nodes; node++) {
			graph.addEdge(1L << node - 1, 1L << node);
		}
		return graph;
	}

	private static PackedJoinHypergraph randomGraph(Random random) {
		int nodes = 2 + random.nextInt(8);
		PackedJoinHypergraph graph = new PackedJoinHypergraph(nodes);
		double probability = new double[] { 0.15d, 0.3d, 0.6d }[random.nextInt(3)];
		for (int left = 0; left < nodes; left++) {
			for (int right = left + 1; right < nodes; right++) {
				if (random.nextDouble() < probability) {
					graph.addEdge(1L << left, 1L << right);
				}
			}
		}
		for (int edge = random.nextInt(4); edge > 0; edge--) {
			long left = randomSet(random, nodes);
			long right = randomSet(random, nodes) & ~left;
			if (left != 0L && right != 0L) {
				graph.addEdge(left, right);
			}
		}
		return graph;
	}

	private static long randomSet(Random random, int nodes) {
		long result = 0L;
		for (int count = 1 + random.nextInt(3); count > 0; count--) {
			result |= 1L << random.nextInt(nodes);
		}
		return result;
	}

	private static Set<Pair> oraclePairs(PackedJoinHypergraph graph) {
		int nodes = graph.nodeCount();
		boolean[] connected = new boolean[1 << nodes];
		Set<Pair> pairs = new LinkedHashSet<>();
		for (long set = 1L; set < 1L << nodes; set++) {
			if (Long.bitCount(set) == 1) {
				connected[(int) set] = true;
				continue;
			}
			long lowest = set & -set;
			for (long left = nextSubset(0L, set); left != 0L; left = nextSubset(left, set)) {
				if (left == set || (left & lowest) == 0L) {
					continue;
				}
				long right = set & ~left;
				if (connected[(int) left] && connected[(int) right] && directlyConnected(graph, left, right)) {
					pairs.add(new Pair(left, right));
					connected[(int) set] = true;
				}
			}
		}
		return pairs;
	}

	private static boolean directlyConnected(PackedJoinHypergraph graph, long left, long right) {
		for (int edge = 0; edge < graph.edgeCount(); edge++) {
			long edgeLeft = graph.edgeLeft(edge);
			long edgeRight = graph.edgeRight(edge);
			if ((edgeLeft & ~left) == 0L && (edgeRight & ~right) == 0L
					|| (edgeLeft & ~right) == 0L && (edgeRight & ~left) == 0L) {
				return true;
			}
		}
		return false;
	}

	private static long nextSubset(long subset, long superset) {
		return (subset - superset) & superset;
	}

	private record Pair(long left, long right) {
	}

	private static final class RecordingReceiver implements PackedDphypEnumerator.Receiver {

		private final PackedJoinHypergraph graph;
		private final Set<Long> seen = new HashSet<>();
		private final Set<Pair> pairs = new LinkedHashSet<>();

		private RecordingReceiver(PackedJoinHypergraph graph) {
			this.graph = graph;
		}

		@Override
		public boolean hasSeen(long nodes) {
			return seen.contains(nodes);
		}

		@Override
		public boolean foundSingleNode(int node) {
			assertTrue(seen.add(1L << node));
			return false;
		}

		@Override
		public boolean foundSubgraphPair(long left, long right, int edge) {
			assertTrue(seen.contains(left), "left side must be available before its CSG/CMP callback");
			assertTrue(seen.contains(right), "right side must be available before its CSG/CMP callback");
			assertFalse((left & right) != 0L);
			assertTrue((left & Long.lowestOneBit(left | right)) != 0L,
					"the canonical left side must contain the union's lowest node");
			long edgeLeft = graph.edgeLeft(edge);
			long edgeRight = graph.edgeRight(edge);
			assertTrue((edgeLeft & ~left) == 0L && (edgeRight & ~right) == 0L
					|| (edgeLeft & ~right) == 0L && (edgeRight & ~left) == 0L);
			assertTrue(pairs.add(new Pair(left, right)), "DPhyp must emit each partition once");
			seen.add(left | right);
			return false;
		}
	}
}
